CREATE TABLE public.template_field_rules (template_id uuid NOT NULL REFERENCES public.report_templates(id) ON DELETE CASCADE, field_key text NOT NULL, required boolean NOT NULL DEFAULT true, PRIMARY KEY(template_id,field_key));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.template_field_rules TO authenticated;
GRANT ALL ON public.template_field_rules TO service_role;
ALTER TABLE public.template_field_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY rule_read ON public.template_field_rules FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.report_templates t WHERE t.id=template_id AND t.school_id=public.current_user_school_id()));
CREATE POLICY rule_manage ON public.template_field_rules FOR ALL TO authenticated USING((public.has_role(auth.uid(),'admin') OR public.is_super_admin()) AND EXISTS(SELECT 1 FROM public.report_templates t WHERE t.id=template_id AND t.school_id=public.current_user_school_id())) WITH CHECK((public.has_role(auth.uid(),'admin') OR public.is_super_admin()) AND EXISTS(SELECT 1 FROM public.report_templates t WHERE t.id=template_id AND t.school_id=public.current_user_school_id()));
CREATE TABLE public.template_verifications (template_id uuid PRIMARY KEY REFERENCES public.report_templates(id) ON DELETE CASCADE, school_id uuid NOT NULL REFERENCES public.schools(id), level text NOT NULL, learner_id uuid NOT NULL, term_id uuid NOT NULL REFERENCES public.terms(id), academic_year integer NOT NULL, verified_by uuid NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), configuration_hash text NOT NULL, results jsonb NOT NULL);
GRANT SELECT ON public.template_verifications TO authenticated;
GRANT ALL ON public.template_verifications TO service_role;
ALTER TABLE public.template_verifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY verification_read ON public.template_verifications FOR SELECT TO authenticated USING(school_id=public.current_user_school_id());
CREATE FUNCTION public.template_configuration_hash(tid uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT md5(jsonb_build_array((SELECT to_jsonb(t) - 'is_active' - 'updated_at' FROM public.report_templates t WHERE t.id=tid), (SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.report_field_associations a WHERE a.template_id=tid), (SELECT jsonb_agg(to_jsonb(r) ORDER BY r.field_key) FROM public.template_field_rules r WHERE r.template_id=tid), (SELECT jsonb_agg(jsonb_build_array(d.id,d.archived) ORDER BY d.id) FROM public.report_field_definitions d JOIN public.report_field_associations a ON a.definition_id=d.id WHERE a.template_id=tid))::text) $$;
REVOKE ALL ON FUNCTION public.template_configuration_hash(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.template_system_source(k text,lvl text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT (k=ANY(ARRAY['school.name','school.motto','school.location','school.tel','school.email','learner.full.name','learner.age','learner.sex','learner.house','learner.conduct','learner.co.curricular','learner.lin.no','learner.reg.no','learner.pay.code','class.name','stream.name','term.name','academic.year','term.next.begins.on','term.ends.on','report.class.teacher.comment','report.head.teacher.comment','bot.total','bot.average','bot.aggregate','bot.division','bot.position','mid.total','mid.average','mid.aggregate','mid.division','mid.position','eot.total','eot.average','eot.aggregate','eot.division','eot.position','school.po.box','school.website','learner.dob','learner.index.no','learner.section','class.teacher.name','head.teacher.name','eot.class.size','bot.class.size','mid.class.size']::text[]) AND (lvl='primary' OR k !~ '^(bot|mid|eot)[.]')) OR (lvl='primary' AND k ~ '^subject[.][a-z0-9.]+[.](name|code|full[.]marks|grade|points|remark|initials|bot|mid|eot|(bot|mid|eot)[.](grade|points))$') OR (lvl='nursery' AND k ~ '^learning[.]area[.][a-z0-9.]+[.](name|grade|comment)$') $$;
REVOKE ALL ON FUNCTION public.template_system_source(text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.template_auto_source(n text,lvl text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
DECLARE k text; candidate text; aliases jsonb := '{"school.name":"school.name","schoolname":"school.name","learner.name":"learner.full.name","student.name":"learner.full.name","pupil.name":"learner.full.name","full.name":"learner.full.name","name":"learner.full.name","class":"class.name","stream":"stream.name","term":"term.name","year":"academic.year","age":"learner.age","sex":"learner.sex","house":"learner.house","section":"learner.section","lin.no":"learner.lin.no","index.no":"learner.index.no","reg.no":"learner.reg.no","pay.code":"learner.pay.code","admission.no":"learner.reg.no","registration.no":"learner.reg.no","dob":"learner.dob","date.of.birth":"learner.dob","conduct":"learner.conduct","co.curricular":"learner.co.curricular","class.teacher":"class.teacher.name","head.teacher":"head.teacher.name","class.teacher.comment":"report.class.teacher.comment","class.teachers.comment":"report.class.teacher.comment","head.teacher.comment":"report.head.teacher.comment","head.teachers.comment":"report.head.teacher.comment","next.term.begins":"term.next.begins.on","next.term.begins.on":"term.next.begins.on","next.term":"term.next.begins.on","ends.on":"term.ends.on","term.ends":"term.ends.on","motto":"school.motto","location":"school.location","tel":"school.tel","telephone":"school.tel","po.box":"school.po.box","school.email":"school.email","website":"school.website","total":"eot.total","total.marks":"eot.total","average":"eot.average","aggregate":"eot.aggregate","aggregates":"eot.aggregate","division":"eot.division","position":"eot.position","class.size":"eot.class.size","out.of":"eot.class.size"}'::jsonb; images jsonb := '{"logo":"logo","school.logo":"logo","school.badge":"logo","badge":"logo","photo":"photo","learner.photo":"photo","student.photo":"photo","pupil.photo":"photo","stamp":"stamp","school.stamp":"stamp","head.teacher.signature":"headSig","head.signature":"headSig","headteacher.signature":"headSig","class.teacher.signature":"classSig","class.signature":"classSig","classteacher.signature":"classSig"}'::jsonb;
BEGIN k:=trim(both '.' from regexp_replace(regexp_replace(regexp_replace(lower(trim(n)),'[[:space:]_-]+','.','g'),'[^a-z0-9.]+','','g'),'[.]+','.','g')); IF images ? k THEN RETURN 'image:'||(images->>k); END IF; FOREACH candidate IN ARRAY ARRAY[coalesce(aliases->>k,k),k,'learner.'||k,'school.'||k,'report.'||k,'term.'||k,'class.'||k,'eot.'||k] LOOP IF public.template_system_source(candidate,lvl) THEN RETURN candidate; END IF; END LOOP; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.template_auto_source(text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.record_template_verification(_template_id uuid,_learner_id uuid,_term_id uuid,_academic_year integer,_results jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE t public.report_templates; item jsonb; expected text; k text; needed boolean;
BEGIN SELECT * INTO t FROM public.report_templates WHERE id=_template_id AND school_id=public.current_user_school_id(); IF t.id IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.is_super_admin()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.terms WHERE id=_term_id AND school_id=t.school_id) OR NOT EXISTS(SELECT 1 FROM public.academic_years WHERE school_id=t.school_id AND year=_academic_year) THEN RAISE EXCEPTION 'Choose a school term and year'; END IF;
IF t.level='primary' THEN IF NOT EXISTS(SELECT 1 FROM public.learners WHERE id=_learner_id AND school_id=t.school_id) THEN RAISE EXCEPTION 'Choose a learner in this school and level'; END IF; ELSE IF NOT EXISTS(SELECT 1 FROM public.nursery_learners WHERE id=_learner_id AND school_id=t.school_id) THEN RAISE EXCEPTION 'Choose a learner in this school and level'; END IF; END IF;
IF jsonb_typeof(_results) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid verification'; END IF;
FOR k IN SELECT jsonb_array_elements_text(t.field_names) UNION ALL SELECT 'placement:'||id FROM public.report_field_associations WHERE template_id=t.id AND pdf_field IS NULL LOOP SELECT v INTO item FROM jsonb_array_elements(_results) v WHERE v->>'key'=k; IF item IS NULL THEN RAISE EXCEPTION 'Verification incomplete'; END IF;
SELECT coalesce(r.required,true) INTO needed FROM (SELECT 1) x LEFT JOIN public.template_field_rules r ON r.template_id=t.id AND r.field_key=k;
SELECT CASE WHEN a.definition_id IS NOT NULL THEN CASE WHEN d.id IS NOT NULL AND NOT d.archived THEN 'custom:'||d.id END WHEN public.template_system_source(a.source_key,t.level) THEN a.source_key END INTO expected FROM public.report_field_associations a LEFT JOIN public.report_field_definitions d ON d.id=a.definition_id WHERE a.template_id=t.id AND (a.pdf_field=k OR 'placement:'||a.id=k); IF NOT FOUND THEN expected:=public.template_auto_source(k,t.level); END IF;
IF item->>'source' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Field association changed; rerun verification'; END IF; IF needed AND expected IS NULL THEN RAISE EXCEPTION 'Required unmatched field: %',k; END IF; END LOOP;
INSERT INTO public.template_verifications(template_id,school_id,level,learner_id,term_id,academic_year,verified_by,configuration_hash,results) VALUES(t.id,t.school_id,t.level,_learner_id,_term_id,_academic_year,auth.uid(),public.template_configuration_hash(t.id),_results) ON CONFLICT(template_id) DO UPDATE SET learner_id=excluded.learner_id,term_id=excluded.term_id,academic_year=excluded.academic_year,verified_by=excluded.verified_by,verified_at=now(),configuration_hash=excluded.configuration_hash,results=excluded.results; END $$;
REVOKE ALL ON FUNCTION public.record_template_verification(uuid,uuid,uuid,integer,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_template_verification(uuid,uuid,uuid,integer,jsonb) TO authenticated,service_role;
CREATE FUNCTION public.require_template_verification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.is_active AND (TG_OP='INSERT' OR NOT OLD.is_active) AND NOT EXISTS(SELECT 1 FROM public.template_verifications v WHERE v.template_id=NEW.id AND v.configuration_hash=public.template_configuration_hash(NEW.id)) THEN RAISE EXCEPTION 'Test this template successfully before activation'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.require_template_verification() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER require_template_verification BEFORE INSERT OR UPDATE OF is_active ON public.report_templates FOR EACH ROW EXECUTE FUNCTION public.require_template_verification();